import json, os, glob
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse

STATUS_DIR = os.environ.get('STATUS_DIR', '/tmp/dashboard')

DASHBOARD_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Farm Dashboard</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap\" rel=\"stylesheet\">\n<style>\n*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }\n\n:root {\n  --bg: #05050f;\n  --surface: #0a0a1a;\n  --surface2: #0f0f22;\n  --border: #1c1c35;\n  --border2: #252545;\n  --accent: #7c3aed;\n  --accent2: #a855f7;\n  --accent3: #c084fc;\n  --blue: #3b82f6;\n  --green: #10b981;\n  --red: #ef4444;\n  --text: #e2e8f0;\n  --text2: #94a3b8;\n  --text3: #475569;\n}\n\nbody {\n  background: var(--bg);\n  color: var(--text);\n  font-family: 'Inter', sans-serif;\n  min-height: 100vh;\n  overflow-x: hidden;\n}\n\n/* Background glow */\nbody::before {\n  content: '';\n  position: fixed;\n  top: -200px;\n  left: 50%;\n  transform: translateX(-50%);\n  width: 800px;\n  height: 400px;\n  background: radial-gradient(ellipse, rgba(124,58,237,0.08) 0%, transparent 70%);\n  pointer-events: none;\n  z-index: 0;\n}\n\n/* HEADER */\nheader {\n  position: sticky;\n  top: 0;\n  z-index: 100;\n  background: rgba(5,5,15,0.85);\n  backdrop-filter: blur(20px);\n  border-bottom: 1px solid var(--border);\n  padding: 0 28px;\n  height: 60px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.logo {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  font-size: 15px;\n  font-weight: 800;\n  color: var(--text);\n  letter-spacing: -0.3px;\n}\n\n.logo-icon {\n  width: 30px;\n  height: 30px;\n  background: linear-gradient(135deg, var(--accent), var(--accent2));\n  border-radius: 8px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 14px;\n  box-shadow: 0 0 20px rgba(124,58,237,0.4);\n}\n\n.header-stats {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.hstat {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: 10px;\n  padding: 7px 14px;\n}\n\n.hstat-val {\n  font-size: 18px;\n  font-weight: 800;\n  background: linear-gradient(135deg, var(--accent2), var(--accent3));\n  -webkit-background-clip: text;\n  -webkit-text-fill-color: transparent;\n}\n\n.hstat-label {\n  font-size: 10px;\n  color: var(--text3);\n  font-weight: 500;\n  text-transform: uppercase;\n  letter-spacing: 0.5px;\n}\n\n.divider { width: 1px; height: 30px; background: var(--border); margin: 0 4px; }\n\n.btn {\n  background: linear-gradient(135deg, var(--accent), var(--accent2));\n  color: white;\n  border: none;\n  padding: 8px 18px;\n  border-radius: 10px;\n  font-size: 12px;\n  font-weight: 600;\n  cursor: pointer;\n  font-family: inherit;\n  box-shadow: 0 0 20px rgba(124,58,237,0.3);\n  transition: opacity 0.2s;\n}\n\n.btn:hover { opacity: 0.85; }\n\n.timer-text { font-size: 11px; color: var(--text3); }\n\n/* MAIN */\nmain {\n  padding: 24px 28px;\n  max-width: 1500px;\n  margin: 0 auto;\n  position: relative;\n  z-index: 1;\n}\n\n.grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));\n  gap: 16px;\n}\n\n/* PHONE CARD */\n.card {\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: 16px;\n  overflow: hidden;\n  position: relative;\n  transition: border-color 0.3s, transform 0.2s;\n}\n\n.card::before {\n  content: '';\n  position: absolute;\n  top: 0; left: 0; right: 0;\n  height: 1px;\n  background: linear-gradient(90deg, transparent, rgba(124,58,237,0.5), transparent);\n  opacity: 0;\n  transition: opacity 0.3s;\n}\n\n.card:hover { transform: translateY(-2px); border-color: var(--border2); }\n.card:hover::before { opacity: 1; }\n.card.running { border-color: rgba(59,130,246,0.3); }\n.card.running::before { opacity: 1; background: linear-gradient(90deg, transparent, rgba(59,130,246,0.5), transparent); }\n.card.error { border-color: rgba(239,68,68,0.3); }\n\n/* Card header */\n.card-head {\n  padding: 16px 18px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  border-bottom: 1px solid var(--border);\n  background: linear-gradient(180deg, var(--surface2) 0%, var(--surface) 100%);\n}\n\n.phone-label {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n.phone-num {\n  width: 40px;\n  height: 40px;\n  border-radius: 12px;\n  background: linear-gradient(135deg, rgba(124,58,237,0.2), rgba(168,85,247,0.1));\n  border: 1px solid rgba(124,58,237,0.3);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 16px;\n  font-weight: 900;\n  color: var(--accent3);\n}\n\n.phone-meta { line-height: 1; }\n.phone-title { font-size: 14px; font-weight: 700; color: var(--text); }\n.phone-ip { font-size: 11px; color: var(--text3); margin-top: 3px; font-family: monospace; }\n\n.pill {\n  font-size: 11px;\n  font-weight: 600;\n  padding: 4px 12px;\n  border-radius: 20px;\n  display: flex;\n  align-items: center;\n  gap: 5px;\n}\n\n.pill-running { background: rgba(59,130,246,0.1); color: #60a5fa; border: 1px solid rgba(59,130,246,0.2); }\n.pill-idle { background: rgba(71,85,105,0.15); color: var(--text3); border: 1px solid var(--border); }\n.pill-error { background: rgba(239,68,68,0.1); color: #f87171; border: 1px solid rgba(239,68,68,0.2); }\n\n.dot { width: 6px; height: 6px; border-radius: 50%; background: #3b82f6; animation: pulse 2s infinite; }\n@keyframes pulse { 0%,100%{opacity:1;transform:scale(1)} 50%{opacity:0.4;transform:scale(0.8)} }\n\n/* Card body */\n.card-body { padding: 16px 18px; }\n\n.prog-row { display: flex; justify-content: space-between; align-items: center; margin-bottom: 7px; }\n.prog-label { font-size: 11px; color: var(--text3); font-weight: 500; }\n.prog-val { font-size: 11px; color: var(--accent3); font-weight: 700; }\n\n.prog-bar {\n  height: 4px;\n  background: var(--border);\n  border-radius: 4px;\n  margin-bottom: 16px;\n  overflow: hidden;\n}\n\n.prog-fill {\n  height: 100%;\n  border-radius: 4px;\n  background: linear-gradient(90deg, var(--accent), var(--accent2), var(--accent3));\n  box-shadow: 0 0 8px rgba(124,58,237,0.5);\n}\n\n.stats-row {\n  display: grid;\n  grid-template-columns: 1fr 1fr 1fr;\n  gap: 8px;\n  margin-bottom: 14px;\n}\n\n.stat-box {\n  background: var(--bg);\n  border: 1px solid var(--border);\n  border-radius: 10px;\n  padding: 10px 8px;\n  text-align: center;\n}\n\n.stat-box:hover { border-color: var(--border2); }\n\n.stat-val {\n  font-size: 20px;\n  font-weight: 800;\n  background: linear-gradient(135deg, var(--accent2), var(--accent3));\n  -webkit-background-clip: text;\n  -webkit-text-fill-color: transparent;\n  line-height: 1;\n}\n\n.stat-lbl {\n  font-size: 9px;\n  color: var(--text3);\n  text-transform: uppercase;\n  letter-spacing: 0.8px;\n  margin-top: 4px;\n  font-weight: 500;\n}\n\n.vid-row {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  background: var(--bg);\n  border: 1px solid var(--border);\n  border-radius: 8px;\n  padding: 7px 10px;\n  margin-bottom: 14px;\n}\n\n.vid-icon { font-size: 10px; }\n.vid-name { font-size: 10px; color: var(--text3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-family: monospace; }\n\n/* Accounts */\n.accs-head {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 8px;\n  padding-top: 14px;\n  border-top: 1px solid var(--border);\n}\n\n.accs-title { font-size: 10px; color: var(--text3); font-weight: 600; text-transform: uppercase; letter-spacing: 0.8px; }\n.accs-count { font-size: 10px; color: var(--accent3); font-weight: 700; }\n\n.accs-list {\n  display: flex;\n  flex-direction: column;\n  gap: 3px;\n  max-height: 170px;\n  overflow-y: auto;\n  scrollbar-width: thin;\n  scrollbar-color: var(--border) transparent;\n}\n\n.acc-row {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 6px 10px;\n  border-radius: 8px;\n  border: 1px solid transparent;\n  background: var(--bg);\n  transition: border-color 0.2s;\n}\n\n.acc-row:hover { border-color: var(--border); }\n.acc-row.active {\n  border-color: rgba(124,58,237,0.4);\n  background: rgba(124,58,237,0.07);\n}\n\n.acc-name { font-size: 11px; color: var(--text2); font-weight: 500; }\n.acc-row.active .acc-name { color: var(--accent3); font-weight: 600; }\n.acc-followers { font-size: 11px; font-weight: 700; color: var(--accent2); }\n</style>\n</head>\n<body>\n<header>\n  <div class=\"logo\">\n    <div class=\"logo-icon\">\u2b21</div>\n    Farm Dashboard\n  </div>\n  <div class=\"header-stats\">\n    <div class=\"hstat\">\n      <div class=\"hstat-val\" id=\"h-accounts\">137</div>\n      <div class=\"hstat-label\">Accounts</div>\n    </div>\n    <div class=\"divider\"></div>\n    <div class=\"hstat\">\n      <div class=\"hstat-val\" id=\"h-reels\">\u2014</div>\n      <div class=\"hstat-label\">Reels Today</div>\n    </div>\n    <div class=\"divider\"></div>\n    <div class=\"hstat\">\n      <div class=\"hstat-val\" id=\"h-active\">\u2014</div>\n      <div class=\"hstat-label\">Active Phones</div>\n    </div>\n    <div class=\"divider\"></div>\n    <span class=\"timer-text\" id=\"timer\">30s</span>\n    <button class=\"btn\" onclick=\"load()\">\u21bb Refresh</button>\n  </div>\n</header>\n\n<main>\n  <div class=\"grid\" id=\"grid\"></div>\n</main>\n\n<script>\nconst PHONES = {\n  1:{ip:'192.168.1.9',accounts:10},\n  2:{ip:'192.168.1.12',accounts:30},\n  3:{ip:'192.168.1.14',accounts:20},\n  4:{ip:'192.168.1.10',accounts:20},\n  5:{ip:'192.168.1.11',accounts:19},\n  6:{ip:'192.168.1.15',accounts:20},\n  7:{ip:'192.168.1.13',accounts:18}\n};\n\nfunction fmt(n){if(!n||n==='?')return'\u2014';n=parseInt(n);if(n>=1000)return(n/1000).toFixed(1)+'K';return n;}\n\nasync function load(){\n  let totalReels=0,active=0;\n  const grid=document.getElementById('grid');\n  grid.innerHTML='';\n  for(const[num,cfg]of Object.entries(PHONES)){\n    let s=null;\n    try{const r=await fetch('/status/'+num,{signal:AbortSignal.timeout(3000)});s=await r.json();}catch(e){}\n    const running=s?.status==='running';\n    const error=s?.status==='error';\n    if(running)active++;\n    if(s)totalReels+=s.reels_posted||0;\n    const pct=s?Math.min(100,Math.round((s.container/s.total_containers)*100)):0;\n    const accounts=s?.accounts||{};\n    const card=document.createElement('div');\n    card.className='card'+(running?' running':error?' error':'');\n    const accRows=Array.from({length:cfg.accounts},(_,i)=>{\n      const acc=accounts[i+1]||{};\n      const isActive=s?.current_container===i+1;\n      return`<div class=\"acc-row${isActive?' active':''}\"><span class=\"acc-name\">Account ${i+1}</span><span class=\"acc-followers\">${acc.followers?fmt(acc.followers):'\u2014'}</span></div>`;\n    }).join('');\n    card.innerHTML=`\n      <div class=\"card-head\">\n        <div class=\"phone-label\">\n          <div class=\"phone-num\">${num}</div>\n          <div class=\"phone-meta\">\n            <div class=\"phone-title\">Phone ${num}</div>\n            <div class=\"phone-ip\">${cfg.ip}</div>\n          </div>\n        </div>\n        <div class=\"pill ${running?'pill-running':error?'pill-error':'pill-idle'}\">\n          ${running?'<span class=\"dot\"></span>':''}${running?'Running':error?'Error':'Idle'}\n        </div>\n      </div>\n      <div class=\"card-body\">\n        <div class=\"prog-row\">\n          <span class=\"prog-label\">Container ${s?s.container:0} / ${s?s.total_containers:cfg.accounts}</span>\n          <span class=\"prog-val\">${pct}%</span>\n        </div>\n        <div class=\"prog-bar\"><div class=\"prog-fill\" style=\"width:${pct}%\"></div></div>\n        <div class=\"stats-row\">\n          <div class=\"stat-box\"><div class=\"stat-val\">${cfg.accounts}</div><div class=\"stat-lbl\">Accounts</div></div>\n          <div class=\"stat-box\"><div class=\"stat-val\">${s?.reels_posted??'\u2014'}</div><div class=\"stat-lbl\">Reels</div></div>\n          <div class=\"stat-box\"><div class=\"stat-val\">${s?.reels_verified??'\u2014'}</div><div class=\"stat-lbl\">Verified</div></div>\n        </div>\n        ${s?.current_video?`<div class=\"vid-row\"><span class=\"vid-icon\">\u25b6</span><span class=\"vid-name\">${s.current_video}</span></div>`:''}\n        <div class=\"accs-head\">\n          <span class=\"accs-title\">Accounts</span>\n          <span class=\"accs-count\">${cfg.accounts} total</span>\n        </div>\n        <div class=\"accs-list\">${accRows}</div>\n      </div>`;\n    grid.appendChild(card);\n  }\n  document.getElementById('h-reels').textContent=totalReels||'\u2014';\n  document.getElementById('h-active').textContent=active||'\u2014';\n  startTimer();\n}\n\nlet t;\nfunction startTimer(){\n  clearInterval(t);let s=30;\n  document.getElementById('timer').textContent=s+'s';\n  t=setInterval(()=>{s--;document.getElementById('timer').textContent=s+'s';if(s<=0){clearInterval(t);load();}},1000);\n}\nload();\n</script>\n</body>\n</html>\n"

class Handler(BaseHTTPRequestHandler):
    def log_message(self, *args): pass

    def do_OPTIONS(self):
        self.send_response(200)
        self.send_header('Access-Control-Allow-Origin', '*')
        self.end_headers()

    def do_GET(self):
        path = urlparse(self.path).path
        if path == '/' or path == '/dashboard':
            self.send_response(200)
            self.send_header('Content-Type', 'text/html')
            self.send_header('Cache-Control', 'no-cache, no-store, must-revalidate')
            self.end_headers()
            self.wfile.write(DASHBOARD_HTML.encode())
            return
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Access-Control-Allow-Origin', '*')
        self.end_headers()
        if path.startswith('/status/'):
            phone = path.split('/')[-1]
            fpath = os.path.join(STATUS_DIR, f'phone_{phone}_status.json')
            if os.path.exists(fpath):
                with open(fpath) as f: self.wfile.write(f.read().encode())
            else: self.wfile.write(b'null')
        elif path == '/all':
            result = {}
            os.makedirs(STATUS_DIR, exist_ok=True)
            for fpath in glob.glob(os.path.join(STATUS_DIR, 'phone_*_status.json')):
                num = os.path.basename(fpath).split('_')[1]
                try:
                    with open(fpath) as f: result[num] = json.load(f)
                except: pass
            self.wfile.write(json.dumps(result).encode())
        else: self.wfile.write(b'{}')

    def do_POST(self):
        path = urlparse(self.path).path
        length = int(self.headers.get('Content-Length', 0))
        body = self.rfile.read(length)
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Access-Control-Allow-Origin', '*')
        self.end_headers()
        if path.startswith('/update/'):
            phone = path.split('/')[-1]
            os.makedirs(STATUS_DIR, exist_ok=True)
            fpath = os.path.join(STATUS_DIR, f'phone_{phone}_status.json')
            with open(fpath, 'wb') as f: f.write(body)
            self.wfile.write(b'{"ok":true}')
        else: self.wfile.write(b'{}')

if __name__ == '__main__':
    os.makedirs(STATUS_DIR, exist_ok=True)
    port = int(os.environ.get('PORT', 5050))
    print(f'Dashboard running on port {port}')
    HTTPServer(('0.0.0.0', port), Handler).serve_forever()
